<script setup lang="ts">
import {ref,watch} from 'vue'
import {ApiError,rowsOf,type Api,type Row} from '../lib/api'
import {useAccess} from '../lib/access'
const props=defineProps<{api:Api,facility:string,flatSheet?:string}>(), emit=defineEmits<{contexts:[Row[]]}>(), can=useAccess()
const alias=ref(''),scope=ref(props.flatSheet ?? ''),stage=ref(''),unit=ref(''),contexts=ref<Row[]>([]),queue=ref<Row[]>([]),proposals=ref<Row[]>([]),error=ref(''),success=ref(''),busy=ref(false)
const selected=ref(''),metric=ref(''),item=ref(''),measure=ref(''),report=ref(''),reason=ref(''),reviewReason=ref('')
watch(()=>props.facility,()=>{contexts.value=[];emit('contexts',[]);queue.value=[];proposals.value=[]})
watch(()=>props.flatSheet,()=>{contexts.value=[];emit('contexts',[]);scope.value=props.flatSheet ?? ''})
function add(){if(contexts.value.some(c=>c.alias===alias.value)){error.value='أُضيف اسم العمود مسبقًا.';return}const sourceScope=props.flatSheet || scope.value;const locator:Row={row:1,column:alias.value};if(props.flatSheet)locator.sheet=props.flatSheet;contexts.value.push({alias:alias.value,source_scope:sourceScope,unit_code:unit.value,granularity:'monthly',product_stage:stage.value,locator});emit('contexts',[...contexts.value]);alias.value='';scope.value=props.flatSheet ?? '';stage.value='';unit.value='';error.value=''}
function remove(index:number){contexts.value.splice(index,1);emit('contexts',[...contexts.value])}
async function load(){if(!props.facility)return;busy.value=true;error.value='';try{const q='?facility_id='+encodeURIComponent(props.facility);queue.value=rowsOf(await props.api('/source-mappings/unresolved'+q));proposals.value=rowsOf(await props.api('/source-mappings/proposals'+q))}catch(e){error.value=e instanceof ApiError?e.message:'تعذر تحميل مراجعات الربط'}finally{busy.value=false}}
async function propose(){busy.value=true;error.value='';try{await props.api('/source-mappings/proposals',{method:'POST',body:{queue_id:selected.value,metric_code:metric.value,item_code:item.value,actual_or_target:measure.value,report_status:report.value,reason:reason.value}});success.value='حُفظ الاقتراح بانتظار مراجعة مستقلة.';await load()}catch(e){error.value=e instanceof ApiError?e.message:'تعذر حفظ الاقتراح'}finally{busy.value=false}}
async function approve(id:unknown){if(reviewReason.value.trim().length<10){error.value='أدخل سبب المراجعة المستقلة.';return}busy.value=true;try{await props.api(`/source-mappings/proposals/${id}/approve`,{method:'POST',body:{reason:reviewReason.value}});success.value='اعتمد الربط؛ أعد رفع الملف بالسياق نفسه.';await load()}catch(e){error.value=e instanceof ApiError?e.message:'تعذر اعتماد الربط'}finally{busy.value=false}}
</script>
<template><section class="panel"><h2>قاموس ربط أعمدة CSV</h2><p>أدخل اسم العمود كما في المصدر ونطاقه ووحدته ومرحلته. العمود غير المعروف ينتظر اقتراحًا واعتمادًا مستقلاً قبل استيراد قيمه.</p><p v-if="error" role="alert" class="notice danger">{{ error }}</p><p v-if="success" role="status">{{ success }}</p>
<form v-if="can('imports.write')" data-test="add-context" class="compact-form" @submit.prevent="add"><label>اسم العمود<input v-model="alias" name="alias" maxlength="128" required /></label><label>نطاق المصدر<input v-model="scope" name="source_scope" maxlength="255" placeholder="اسم الورقة أو القسم" required /></label><label>الوحدة<select v-model="unit" name="unit_code" required><option value="">اختر</option><option value="t">طن متري</option></select></label><label>المرحلة<select v-model="stage" name="product_stage" required><option value="">اختر</option><option value="unknown">غير محسومة</option><option value="not_applicable">لا تنطبق</option><option value="intermediate_stream">تيار وسيط</option><option value="final_product">منتج نهائي</option><option value="fuel">وقود</option><option value="byproduct">منتج ثانوي</option><option value="waste">مخلفات</option></select></label><button class="button secondary">إضافة سياق العمود الشهري</button></form><ul><li v-for="(c,i) in contexts" :key="String(c.alias)">{{ c.alias }} — {{ c.source_scope }} — {{ c.product_stage }} <button type="button" @click="remove(i)">إزالة</button></li></ul><p v-if="contexts.length">ارفع الملف بعد إضافة جميع الأعمدة غير المعروفة؛ يلزم استعمال السياق نفسه عند إعادة الرفع.</p>
<button v-if="can('imports.read')" type="button" class="button secondary" :disabled="!facility || busy" @click="load">تحديث قائمة المراجعة للمرفق</button>
<div v-if="queue.length && can('imports.write')"><h3>اقتراح ربط للعمود المجهول</h3><form class="compact-form" @submit.prevent="propose"><label>العمود<select v-model="selected" required><option value="">اختر</option><option v-for="q in queue" :key="String(q.id)" :value="String(q.id)">{{ q.alias }} — {{ q.source_scope }} — {{ q.product_stage }}</option></select></label><label>نوع المقياس<select v-model="metric" required><option value="">اختر</option><option value="product">منتج</option><option value="feed">خام</option></select></label><label>الرمز المعتمد<input v-model="item" pattern="[A-Z0-9_]+" required /></label><label>نوع القيمة<select v-model="measure" required><option value="">اختر</option><option value="actual">فعلي</option><option value="target">مستهدف</option></select></label><label>حالة التقرير<select v-model="report" required><option value="">اختر</option><option value="actual">فعلي</option><option value="semi_actual">شبه فعلي</option></select></label><label>سبب الربط<textarea v-model="reason" minlength="10" required /></label><button class="button primary" :disabled="busy">إرسال للمراجعة</button></form></div>
<div v-if="proposals.length"><h3>اقتراحات تنتظر المراجعة</h3><label v-if="can('imports.approve')">قرار المراجع<textarea v-model="reviewReason" minlength="10" /></label><ul><li v-for="p in proposals" :key="String(p.id)">{{ p.metric_code }} · {{ p.item_code }} · {{ p.actual_or_target }} · {{ p.report_status }} <button v-if="can('imports.approve')" type="button" :disabled="busy" @click="approve(p.id)">اعتماد مستقل</button></li></ul></div>
</section></template>
